<script setup lang="ts">
import UiSelect from './UiSelect.vue'
import {onMounted,ref} from 'vue'
import {api,request} from '../api'
import {useWorkspace} from '../workspace'
import {bytes,type Settings} from '../domain'
import Modal from './Modal.vue'
import Icon from './Icon.vue'
import {applyTheme,type Theme} from '../theme'
const w=useWorkspace(),settings=ref<Settings|null>(null),busy=ref(false),error=ref(''),tokenInput=ref(''),tokenForm=ref(false),theme=ref(document.documentElement.dataset.theme||'light'),warningGiB=ref(1),hardGiB=ref(2),responseKiB=ref(64),preview=ref<Record<string,any>|null>(null)
async function load(){try{settings.value=await api.settings();warningGiB.value=(settings.value.monitor_storage_warning_bytes||1073741824)/1073741824;hardGiB.value=(settings.value.monitor_storage_hard_bytes||2147483648)/1073741824;responseKiB.value=(settings.value.monitor_budget_response_bytes||65536)/1024}catch(e){error.value=e instanceof Error?e.message:String(e)}}
function setTheme(value:Theme){theme.value=value;void applyTheme(value).catch(w.fail)}
async function save(){if(!settings.value)return;error.value='';if(warningGiB.value<=0||warningGiB.value>=hardGiB.value){error.value='容量告警阈值须小于保护阈值，且都大于 0';return}busy.value=true;try{const s={...settings.value,monitor_storage_warning_bytes:Math.round(warningGiB.value*1073741824),monitor_storage_hard_bytes:Math.round(hardGiB.value*1073741824),monitor_budget_response_bytes:Math.round(responseKiB.value*1024)};await api.saveSettings(s);w.settings.value=s;w.notify('设置已保存')}catch(e){error.value=e instanceof Error?e.message:String(e)}finally{busy.value=false}}
async function setToken(){busy.value=true;error.value='';try{await api.setToken(tokenInput.value);w.token.value=await api.token();tokenInput.value='';tokenForm.value=false;w.notify('凭据已保存')}catch(e){error.value=e instanceof Error?e.message:String(e)}finally{busy.value=false}}
async function retentionPreview(){if(!settings.value)return;busy.value=true;try{preview.value=await request('/api/monitor/retention/preview','POST',{policy:settings.value.monitor_retention_policy,custom_days:settings.value.monitor_retention_custom_days},'PreviewMonitorRetention',[{policy:settings.value.monitor_retention_policy,custom_days:settings.value.monitor_retention_custom_days}])}catch(e){error.value=e instanceof Error?e.message:String(e)}finally{busy.value=false}}
async function applyRetention(){if(!settings.value||!preview.value)return;busy.value=true;try{const body={policy:preview.value.policy,custom_days:settings.value.monitor_retention_custom_days,cutoff_time:preview.value.cutoff};const result=await request<Record<string,any>>('/api/monitor/retention','POST',body,'ApplyRetention',[body]);preview.value=null;w.notify(`已清理 ${result.samples_deleted} 条旧采样`)}catch(e){error.value=e instanceof Error?e.message:String(e)}finally{busy.value=false}}
onMounted(load)
</script>
<template><section class="page-view settings-view"><div class="page-header"><div><h1>偏好设置</h1><p>外观、监测请求和数据保存策略。</p></div><button class="button primary" :disabled="busy||!settings" @click="save">保存设置</button></div><p v-if="error" class="inline-error" role="alert">{{error}}</p><section class="settings-section"><h2>外观</h2><div class="theme-choices"><button class="button" :class="{active:theme==='light'}" @click="setTheme('light')"><Icon name="sun"/>浅色</button><button class="button" :class="{active:theme==='dark'}" @click="setTheme('dark')"><Icon name="moon"/>深色</button></div></section><template v-if="settings"><section class="settings-section"><h2>监测请求</h2><p>设置持续监测的并发数与单次响应读取量。</p><div class="form-grid"><label>最大并发请求<input v-model.number="settings.monitor_budget_max_concurrent" type="number" min="1" max="64"></label><label>单次响应读取上限 · KiB<input v-model.number="responseKiB" type="number" min="1"></label></div></section><section class="settings-section"><h2>历史容量</h2><div class="form-grid"><label>告警阈值 · GiB<input v-model.number="warningGiB" type="number" min="0.01" step="0.1"></label><label>保护阈值 · GiB<input v-model.number="hardGiB" type="number" min="0.01" step="0.1"></label><label>监测原始样本保存<UiSelect v-model="settings.monitor_retention_policy"><option value="keep_all">全部保留</option><option value="30d">最近 30 天</option><option value="90d">最近 90 天</option><option value="180d">最近 180 天</option><option value="custom">自定义天数</option></UiSelect></label><label v-if="settings.monitor_retention_policy==='custom'">保存天数<input v-model.number="settings.monitor_retention_custom_days" type="number" min="1" max="36500"></label></div><button v-if="settings.monitor_retention_policy!=='keep_all'" class="button" :disabled="busy" @click="retentionPreview">预览旧采样清理</button></section><section class="settings-section"><h2>打开链接</h2><label class="inline-field">首选浏览器<UiSelect v-model="settings.preferred_browser"><option value="auto">自动</option><option value="default">系统默认</option><option value="chrome">Chrome</option><option value="edge">Edge</option></UiSelect></label></section></template><section class="settings-section"><h2>账号凭据</h2><p>{{w.token.value?.has_token?`已绑定 · ${w.token.value.source}`:'尚未绑定 Antigravity 凭据'}}</p><div class="button-group"><button class="button" @click="api.oauth().then(()=>w.notify('已打开账号登录，完成后会更新状态')).catch(w.fail)"><Icon name="key"/>浏览器登录</button><button class="button ghost" @click="tokenForm=true">手动输入 Token</button><button class="button ghost" @click="api.token().then(t=>w.token.value=t).catch(w.fail)">刷新状态</button></div></section><Modal v-if="tokenForm" title="手动绑定凭据" @close="tokenForm=false;tokenInput=''"><label class="form-stack">Token<textarea v-model="tokenInput" rows="4" autocomplete="off" spellcheck="false" placeholder="输入 Token 或 Authorization: Bearer …"/></label><p v-if="error" class="inline-error">{{error}}</p><template #footer><button class="button primary" :disabled="busy||!tokenInput.trim()" @click="setToken">保存凭据</button></template></Modal><Modal v-if="preview" title="清理预览" @close="preview=null"><p>将删除 {{preview.samples_to_delete}} 条旧样本和 {{preview.runs_to_delete}} 条关联运行记录。</p><p class="muted">仅处理 {{preview.cutoff}} 之前的监测记录。删除后无法从本应用恢复。</p><template #footer><button class="button" @click="preview=null">返回</button><button class="button danger-fill" :disabled="busy" @click="applyRetention">执行清理</button></template></Modal></section></template>
